if($reportQ!==''){$where.=" AND (p.full_name LIKE ? OR p.national_id LIKE ? OR p.hh_id LIKE ? OR p.tent LIKE ?)";array_push($args,"%$reportQ%","%$reportQ%","%$reportQ%","%$reportQ%");}
$sql="SELECT p.sector,p.tent,p.national_id,p.full_name,p.gender,p.birth_date,p.social_status,p.family_member,p.hh_id,p.phone,TIMESTAMPDIFF(MONTH,p.birth_date,CURDATE()) age_months FROM profiles p$where ORDER BY p.sector,p.tent,p.full_name";
$q=db()->prepare($sql);$q->execute($args);$rows=$q->fetchAll();
if(isset($_GET['csv'])){if(!can('reports','export'))throw new RuntimeException('Export not allowed');audit('export','reports',null,'filtered report xlsx');xlsx_send('Yarmouk_Filtered_Report.xlsx',array_keys($rows[0]??array_flip(['sector','tent','national_id','full_name','gender','birth_date','social_status','family_member','hh_id','phone','age_months'])),array_map('array_values',$rows),'Report');}
