s[<?=$m?>]" value="<?=e($sec)?>"></label></div><?php endforeach;?></div><button class="primary">حفظ الحساب والصلاحيات</button></form><?php endif;?></section><section class="panel"><h2>الحسابات الحالية</h2><div class="table-wrap"><table><tr><th>Username</th><th>Full name</th><th>Status</th><th>Actions</th></tr><?php foreach(db()->query('SELECT * FROM users ORDER BY id') as $u):?><tr><td><?=e($u['username'])?></td><td><?=e($u['full_name'])?></td><td><?=$u['is_active']?'Active':'Disabled'?></td><td><?php if($u['username']!=='admin'&&can('users','edit')):?><a href="?page=users&edit_user=<?=$u['id']?>">تعديل الصلاحيات</a><?php endif;?></td></tr><?php endforeach;?></table></div></section><?php endif;?>
